@startuml

class WebPortal {
  + versionNumber : string
  + url : string
}

class Building {
  + id : string
  + name : string
  + address : string
  + yearOfConstruction : int
}

class Entry {
  + name : string
  + public : boolean
}

class TextualEntry extends Entry {
}

class NumericEntry extends Entry {
  + value : float
  + unit : string
}

class Image {
  + fileName : string
}

class User {
  + userName : string
  + emailAddress : string
  + password : string
}

class Administrator extends User {
  + idCardNumber : string
}

class Comment {
}

WebPortal "1" -- "*" Building
Building "1" -- "1" User : owner
Building "1" -- "*" Entry
Building "1" --> "1" Image : profilePhoto
Building "*" -- "*" Comment : commented on
User "1" -- "*" Building : manages
User "1" -- "*" Comment : creates
User "1" -- "*" Building : creates
User "1" -- "*" Building : manages

@enduml

